/**
 * Single source of truth for product data at runtime.
 *
 * `src/data/inventory.json` is GENERATED by `npm run inventory:import`.
 * Never hand-edit it and never hard-code product fields elsewhere.
 *
 * The assertions below run whenever the module is imported — during
 * `npm run build`, in `astro dev`, and inside the browser bundle — so a
 * private field leaking into public data fails loudly instead of shipping.
 */

import type { Diamond, PublicInventory } from './types';
import rawInventory from '../data/inventory.json';

/** Owner-only field names that must never appear in public data. */
const PRIVATE_KEYS = [
  'report',
  'reportNumber',
  'reportUrl',
  'video',
  'videoUrl',
  'mediaUrl',
  'media',
  'sourceRow',
  'reviewFlags',
  'colorRaw',
  'availabilityRaw',
] as const;

function fail(message: string): never {
  throw new Error(`[inventory] ${message}`);
}

function assertPublicPayload(data: PublicInventory): void {
  if (!data || !Array.isArray(data.diamonds)) fail('inventory.json has no diamonds array');
  if (data.diamonds.length === 0) fail('inventory.json is empty — run npm run inventory:import');

  const metaKeys = Object.keys(data.meta ?? {});
  for (const key of PRIVATE_KEYS) {
    if (metaKeys.includes(key)) fail(`private field "${key}" found in inventory meta`);
  }

  const seen = new Set<string>();
  data.diamonds.forEach((d: Diamond, index: number) => {
    if (!d || typeof d.id !== 'string' || d.id.trim() === '') {
      fail(`record #${index} has no Stone ID`);
    }
    if (seen.has(d.id)) fail(`duplicate Stone ID "${d.id}" in public inventory`);
    seen.add(d.id);

    for (const key of PRIVATE_KEYS) {
      if (Object.prototype.hasOwnProperty.call(d, key)) {
        fail(`private field "${key}" found on product "${d.id}" — public/private split failed`);
      }
    }
    if (typeof d.weight !== 'number' || !Number.isFinite(d.weight)) {
      fail(`product "${d.id}" has an invalid carat weight`);
    }
    if (typeof d.shape !== 'string' || d.shape.trim() === '') {
      fail(`product "${d.id}" has no shape`);
    }
  });

  if (typeof data.meta?.recordCount === 'number' && data.meta.recordCount !== data.diamonds.length) {
    fail(
      `meta.recordCount (${data.meta.recordCount}) does not match diamonds.length (${data.diamonds.length})`,
    );
  }
}

const inventory = rawInventory as unknown as PublicInventory;
assertPublicPayload(inventory);

/** All public products, in source inventory order. */
export const diamonds: readonly Diamond[] = inventory.diamonds;

/** Import metadata (timestamp, source file name, record count). */
export const inventoryMeta = inventory.meta;

/** Look up a product by Stone ID. */
export function findDiamond(id: string): Diamond | undefined {
  return diamonds.find((d) => d.id === id);
}
